# -*- coding: utf-8 -*-
"""German calendar entries. TEXT = {English name: {type, life, patron}}.

The calendar's life is the short one the day panel shows; the long one is in
tools/saint_lives/de.py, and a saint is written in both places at once so that
neither has to be come back to.

Only the fields that have been written are given; anything absent falls back
to the English.
"""
TEXT = {

"Martyr Tathuil, and his sister, Bebaia":
{"type": "Märtyrer · 2. Jh.", "life": "Die heiligen Märtyrer Tathuil und seine Schwester Bebaia litten zu Edessa in den Tagen des Kaisers Hadrian für Christus, um ihrer kühnen und fruchtbaren Predigt des Evangeliums unter den Heiden willen. Tathuil, den einige Berichte Thiphael nennen, hatte sich vom Dienste der Götzen zum wahren Gott gewandt, und durch seine Worte wurden viele zum Glauben gebracht.", "patron": "Angerufen um kühne Predigt; um standhaftes Bekenntnis."},

"Uncovering of the relics of Saint Gurias, first Archbishop of Kazan, and Saint Barsanuphius, Bishop of Tver":
{"type": "Erzbischof · 16. Jh.", "life": "An diesem Tag begeht die Kirche die Auffindung der Reliquien der heiligen Hierarchen Gurij, des ersten Erzbischofs von Kasan, und Warsonofij, des Bischofs von Twer, die im Jahr 1595 zu Kasan geschah, als in dem Kloster, das Warsonofij gegründet hatte, eine neue steinerne Kirche der Verklärung erbaut wurde und man die Gräber der beiden Hierarchen unter der alten hölzernen Kirche fand.", "patron": "Angerufen um die Missionare; um die Lehrer."},

"Greatmartyr Paraskevi of Iconium":
{"type": "Grossmärtyrerin · 3. Jh.", "life": "Die heilige Grossmärtyrerin Paraskewi von Ikonion lebte im dritten Jahrhundert, einer reichen und frommen Familie geboren, die den Freitag des Leidens des Herrn besonders in Ehren hielt und ihre Tochter darum Paraskewi nannte, was Freitag bedeutet. Da sie von Jugend auf die Reinheit liebte, gelobte sie Christus ihre Jungfräulichkeit und gab nach der Entschlafung ihrer Eltern ihr Vermögen den Armen und widmete sich der Erleuchtung der Heiden ihrer Stadt mit dem Lichte des Evangeliums.", "patron": "Angerufen um die Kaufleute; um die Händler."},

"Saint Maximus, Metropolitan of Kyiv":
{"type": "Metropolit · 14. Jh.", "life": "Der heilige Hierarch Maximos, Metropolit von Kyjiw und ganzer Rus, ein Grieche von Geburt, wurde im Jahr 1283 aus Konstantinopel gesandt, um die Kirche der Rus in der tiefen Nacht des tatarischen Joches zu weiden, als Kyjiw, zweimal verwüstet, halb in Trümmern lag und der Hof des Metropoliten selbst inmitten der Öde kaum unterhalten werden konnte.", "patron": "Angerufen um die Hierarchen; um die Hirtensorge in einem verwüsteten Lande."},

"Martyrs Theodore and his son, John, of Kyiv":
{"type": "Laien · 10. Jh.", "life": "Die heiligen Märtyrer Feodor der Waräger und sein Sohn Iwan waren die ersten Märtyrer des Landes der Rus und lebten im zehnten Jahrhundert zu Kyjiw, in den Tagen vor der Annahme des Glaubens durch den Fürsten Wladimir. Feodor, ein Waräger von Abstammung und ein Christ, war mit seinem jungen Sohne Iwan nach Kyjiw zurückgekehrt.", "patron": "Angerufen um das Bekenntnis vor dem Götzendienste."},

"Venerable Auxentius of Bithynia":
{"type": "Einsiedler · 5. Jh.", "life": "Der ehrwürdige Auxentios von Bithynien war ein Syrer von Geburt, der zu Konstantinopel in die Reitergarde des Kaisers Theodosios des Jüngeren aufstieg, ein Höfling, in der Hauptstadt für Frömmigkeit, Bildung und eine von Kirchenmännern gesuchte Weisheit berühmt; und auf der Höhe jenes Ansehens verschwand er, setzte über die Meerenge nach Bithynien und verbarg sich als Einsiedler auf dem Berge Oxia bei Chalkedon, der bis heute den Namen des Berges des heiligen Auxentios trägt.", "patron": "Angerufen um die Vorsänger; um die, welche das Volk singen lehren."},

"Saint Alexander, Patriarch of Constantinople":
{"type": "Patriarch · 4. Jh.", "life": "Der heilige Hierarch Alexander war Bischof unter dem heiligen Metrophanes, dem ersten Patriarchen von Konstantinopel, und wurde wegen des hohen Alters des Metrophanes an dessen Statt zum Ersten Ökumenischen Konzil nach Nicäa gesandt, wo die arianische Irrlehre verurteilt wurde; und nach der Entschlafung des Metrophanes, der ihn in seinem Testamente genannt hatte, folgte Alexander auf dem Throne der Kaiserstadt nach.", "patron": "Angerufen um die Rechtgläubigkeit gegen den Arianismus."},

"Leavetaking of the Nativity of our Lord":
{"type": "Fest", "life": "Die Verabschiedung der Geburt unseres Herrn, die Apodosis, wird am einunddreissigsten Dezember gehalten, und an ihr singt die Kirche das Fest noch einmal in beinahe seiner ganzen festlichen Fülle, denn die Hymnen und der Kanon von Bethlehem kehren mit voller Kraft wieder wie am Feste selbst, so dass die Zeit nicht verklingt, sondern mit einem letzten Aufleuchten endet und die Tür des Festes von innen mit Gesang geschlossen wird.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Martyr Gerontius, and those with him, of Saint David Gareji Monastery, Georgia":
{"type": "Mönche · 19. Jh.", "life": "Die heiligen Neumärtyrer des Klosters Dawit-Garedscha in der georgischen Wildnis gaben im Sommer des Jahres 1851 ihr Leben für Christus, als ein Heer aus Dagestan über jene alte Lawra herfiel, die der heilige David gegründet hatte. Die Räuber plünderten das Kloster, schleppten seine heiligen Gefässe und Bücher fort und nahmen die Mönche gefangen und folterten und töteten die standhaftesten unter ihnen.", "patron": "Angerufen um die Mönche; um standhaftes Bekenntnis in der Verfolgung."},

"Martyrs Nikephoros, Antoninus, and Germanus of Caesarea, in Palestine":
{"type": "Märtyrer · 4. Jh.", "life": "Die heiligen Märtyrer Antoninos, Nikephoros und Germanos litten um das Jahr 308 zu Kaisareia in Palästina unter der Regierung des Maximinus, als der Statthalter Firmilian die Verfolgung mit öffentlichen Opfern und Schauspielen gegen die Kirche vorantrieb. Während die heidnischen Riten vor der versammelten Stadt gefeiert wurden, traten die drei Christen aus freiem Willen hervor, tadelten vor dem Statthalter die Verehrung lebloser Götzen und bekannten mit lauter Stimme den einen wahren Gott und seinen Christus.", "patron": "Angerufen um Freimütigkeit vor den Verfolgern."},

"Venerable Sebastian of Poshekhonye":
{"type": "Abt · 16. Jh.", "life": "Der ehrwürdige Sewastian von Poschechonje arbeitete um die Wende des sechzehnten Jahrhunderts im Waldlande jenseits der Wolga, einer aus der stillen Schar von Gründern, welche in den Geschlechtern nach Sergij von Radonesch die Lampe des Einsiedlers Fluss um Fluss nach Norden trugen, bis die ganze Wildnis Russlands mit Klöstern durchzogen war.", "patron": "Angerufen um die Gründer; um die Einsiedler der nördlichen Wälder."},

"Hieromartyr Hermogenes, Patriarch of Moscow, Wonderworker of All Russia":
{"type": "Patriarch, Priestermärtyrer · 17. Jh.", "life": "Der Priestermärtyrer Hermogen, Patriarch von Moskau und ganzem Russland, war der Anker, der eine ertrinkende Nation hielt, und er hielt sie aus einer Hungerzelle. Um das Jahr 1530 geboren, diente er als Gemeindepriester zu Kasan und stand im Jahr 1579 bei jenem Ereignisse, das sein Leben bezeichnete, bei der Auffindung der Kasaner Ikone der Gottesmutter, und trug das neu offenbarte Bild mit eigenen Händen in der Prozession und verfasste später den Bericht ihrer Erscheinung und den Gottesdienst zu ihren Ehren, so dass der Priester der erste Geschichtsschreiber der Ikone wurde.", "patron": "Angerufen um die Patriarchen; um die Verteidiger der Seele eines Volkes."},

"Venerable Irenarchus, Abbot of Solovki":
{"type": "Abt · 17. Jh.", "life": "Der ehrwürdige Irinarch empfing im Kloster von Solowki im fernen Norden Russlands die Mönchsweihe, wo er die Gründer jenes heiligen Ortes, die ehrwürdigen Sosima und Sawwatij, in ihren asketischen Mühen eifrig nachahmte. Im Jahr 1614, nach dem Tode des Abtes Antonij, wurde er zu dessen Nachfolger erwählt, und er leitete die Gemeinschaft treu in einem schweren Zeitalter, da das Kloster von Solowki als ein Bollwerk zur Verteidigung der nördlichen Länder gegen die Schweden und die Dänen stand.", "patron": "Angerufen um die Mönche; um das Mönchsleben."},

"Saints Xanthippi and Polyxeni of Spain":
{"type": "Heilige · 2. Jh.", "life": "Die heiligen Xanthippe und Polyxene waren Schwestern aus Spanien, Schülerinnen der Apostel, die im Jahr 109 in Frieden entschliefen. Xanthippe, die Frau des Probus, eines angesehenen Mannes, empfing den Glauben an Christus durch die Predigt des heiligen Apostels Paulus, als das Evangelium zum ersten Male in den fernen Westen gelangte, und diente mit ihrem Manne dem Herrn in Heiligkeit.", "patron": "Angerufen um die Jüngerinnen; um die bewahrte Keuschheit."},

"Apostle Ananias of the Seventy":
{"type": "Apostel der Siebzig · 1. Jh.", "life": "Der heilige Apostel Ananias aus der Zahl der Siebzig war ein Jünger des Herrn, der zu Damaskus wohnte und dem der Herr in einem Gesichte erschien und ihn hiess, in die Gasse zu gehen, die man die Gerade nennt, und dem Saulus von Tarsus die Hände aufzulegen, dem Verfolger der Kirche, der dort blind im Gebete war.", "patron": "Angerufen um die Heilung der Blindheit; um den Gehorsam gegen den Ruf Gottes."},

"Saint Meletius, Archbishop of Khar'kov and Akhtyrsk":
{"type": "Erzbischof · 19. Jh.", "life": "Der heilige Hierarch Meletij, Erzbischof von Charkow und Achtyrka, als Leontowitsch im Poltawaer Lande geboren, war einer jener verborgenen Asketen, welche die synodale Kirche des neunzehnten Jahrhunderts beinahe gegen sich selbst auf ihre Throne erhob. In den Schulen glänzend, lehrte und leitete er an den geistlichen Akademien, war Rektor und Erzieher eines ganzen Geschlechtes von Geistlichen und ging durch das Bischofsamt mehrerer Sitze, ehe er im Jahr 1835 nach Charkow kam.", "patron": "Angerufen um die Hierarchen der Nachtwache; um die Asketen im Amte."},

"Hieromartyr Autonomus, Bishop in Italy":
{"type": "Bischof · 4. Jh.", "life": "Der Priestermärtyrer Autonomos war in den Tagen der Verfolgung Diokletians Bischof in Italien, und da er vor dem Sturme auswich, kam er nach Soreoi in Bithynien, wo ihn ein frommer Mann namens Kornelios aufnahm, und statt in der Sicherheit zu ruhen, gab er sich der unermüdlichen Predigt hin und bekehrte eine so grosse Menge von Heiden, dass er den Kornelios für die von ihm gesammelte Herde zum Diakon und später zum Bischofe weihte.", "patron": "Angerufen um die Missionare; um die missionarische Predigt."},

"Venerable Dositheus, Abbot of Verkneostrov, Pskov":
{"type": "Abt · 15. Jh.", "life": "Der ehrwürdige Dosifej von Werchni Ostrow war ein Schüler des grossen Ältesten Euphrosin von Pskow, unter dessen Führung er in den strengen Überlieferungen der Pskower Wildnis geformt wurde, im Gehorsame, im Fasten und im unaufhörlichen Gebete. Da er einen Ort der Stille suchte, liess er sich auf der Oberen Insel, Werchni Ostrow, unter den Inseln des Pskower Sees nieder, wo die Wasser seine Einsamkeit schirmten.", "patron": "Angerufen um die Mönche; um das Mönchsleben auf den Inseln."},

"Martyr Anastasius the Fuller at Salona in Dalmatia":
{"type": "Märtyrer · 4. Jh.", "life": "Der heilige Märtyrer Anastasios der Walker wurde zu Aquileia in Italien geboren und übte das Handwerk des Walkers zu Salona in Dalmatien in den Tagen der Verfolgung Diokletians. Da er sich weigerte, jenen Glauben zu verbergen, für den andere starben, malte er das Kreuz Christi offen auf die Tür seiner Werkstatt, damit alle Vorübergehenden wüssten, wessen Diener darin arbeitete.", "patron": "Angerufen um die Walker; um die Handwerker."},

"Venerable Sebastian, Abbot of Pshekhonye Monastery, Vologda":
{"type": "Abt · 16. Jh.", "life": "Der ehrwürdige Sewastian von Poschechonje arbeitete um die Wende des sechzehnten Jahrhunderts in den nördlichen Wäldern Russlands und gründete am Flusse Sochot im Lande von Poschechonje gegen Wologda hin eine Einsiedelei der Verklärung des Herrn und sammelte um sich eine Bruderschaft, die auf das strenge gemeinsame Leben gegründet war: nichts wurde besessen, alles geteilt, und jeder Mund von der Arbeit der eigenen Hände genährt.", "patron": "Angerufen um die Weber; um die Mönche, die mit ihren Händen arbeiten."},

"Hieromartyr Silvanus of Gaza":
{"type": "Bischof · 4. Jh.", "life": "Der heilige Priestermärtyrer Silvanos von Gaza war aus jener Stadt gebürtig, zuerst Soldat und hernach Priester, und in seinem Alter wurde er zum Bischofe erhoben und weidete die Kirche von Gaza in den Jahren der grossen Verfolgung. Falsch angeklagt und verurteilt, wurde er zur Zwangsarbeit in den Kupfergruben von Phaeno verurteilt, wo er, betagt und aufgerieben, die erdrückende Mühe mit ungebrochenem Glauben trug, die vielen mit ihm verurteilten Bekenner stärkte und nie aufhörte, sie wie ein wahrer Vater zu unterweisen und zu trösten.", "patron": "Angerufen um die Gefangenen; um die Bergleute."},

"Martyr Arethas and 4,299 Martyrs with him":
{"type": "Märtyrer · 6. Jh.", "life": "Der heilige Märtyrer Arethas und mit ihm viertausendzweihundertneunundneunzig Märtyrer litten im Jahr 523 in der Stadt Nadschran in Arabien, wo der christliche Glaube tiefe Wurzeln geschlagen hatte. Dunaan, der Herrscher der Himjariten und ein Verfolger der Kirche, belagerte die christliche Stadt, und da er sie mit Gewalt nicht nehmen konnte, schwor er falsch, er werde niemandem etwas antun, und stellte die Gläubigen, nachdem man ihn eingelassen hatte, vor die Wahl, Christus zu verleugnen oder zu sterben.", "patron": "Angerufen um die verfolgten Christen; um ganze Städte, die bis in den Tod treu sind."},

"Saint Theodora the Empress":
{"type": "Heilige · 6. Jh.", "life": "Die heilige Kaiserin Theodora, die Gemahlin des heiligen Justinian, wird von der Kirche als eine Büsserin geehrt, welche die Gnade aus der Tiefe auf den Thron erhob. In ihrer Jugend eine Schauspielerin der Theater und eine Frau von berüchtigtem Lebenswandel und eine Zeitlang dem Irrtume der Monophysiten zugeneigt, tat sie von ganzem Herzen Busse.", "patron": "Angerufen um die Busse; um den Schutz der gefallenen Frauen."},

"Glorification of Saint Innocent, Metropolitan of Moscow, Enlightener of the Aleuts, Apostle to the Americas":
{"type": "Metropolit · 19. Jh.", "life": "An diesem Tag begeht die Kirche die Verherrlichung des heiligen Innokentij, des Metropoliten von Moskau, des Erleuchters der Aleuten und Apostels Amerikas, der am sechsten Oktober 1977 auf die Bitte der Orthodoxen Kirche in Amerika von der Russischen Orthodoxen Kirche unter die Heiligen aufgenommen wurde. Er wurde im Jahr 1797 als Iwan Popow-Weniaminow in einem sibirischen Dorfe geboren.", "patron": "Angerufen um die Missionare; um die Übersetzer."},

"Martyrs Akepsimas and Aithalas of Egypt":
{"type": "Märtyrer · 4. Jh.", "life": "Die heiligen Märtyrer Akepsimas und Aithalas litten zu Arbela im Lande Persien in jenen Verfolgungen, welche die persischen Könige gegen die Kirche erhoben, als die Magier die Christen des Reiches drängten, die Sonne und das Feuer zu verehren, und ihre Weigerungen mit Blut besiegelten. Die Überlieferung jener leidenden Kirche berichtet, dass Aithalas selbst zu Arbela ein Priester der Götzen gewesen war, ehe die Gnade Christi ihn fand, so dass die Verfolger einen ihrer eigenen Altardiener an das Evangelium verloren, eine Wunde, die sie nie verziehen.", "patron": "Angerufen um die Kirche unter Persien; um die bekehrten Götzenpriester."},

"Finding of the relics of Monastic Martyr Adrian of Poshekhonsk, Yaroslavl":
{"type": "Abt · 16. Jh.", "life": "An diesem Tag begeht die Kirche die Auffindung der Reliquien des Mönchsmärtyrers Adrian von Poschechonje, die am neunzehnten November 1625 geschah. Der ehrwürdige Adrian, ein Mönch und begabter Ikonenmaler, in der Überlieferung der grossen nördlichen Klöster geformt, hatte mit einem Mitasketen in den Wäldern von Poschechonje im Jaroslawler Lande ein Kloster der Entschlafung der Allheiligen Gottesgebärerin gegründet und arbeitete dort in Fasten, Gebet und im Malen heiliger Ikonen und sammelte um die Kirche in der Wildnis eine Bruderschaft.", "patron": "Angerufen um die Ikonenmaler; um die Mönche."},

"Saint Gurias, Archbishop of Kazan":
{"type": "Erzbischof · 16. Jh.", "life": "Der heilige Hierarch Gurij, der erste Erzbischof von Kasan, in der Welt Grigorij Rugotin, wurde zu Radonesch einer armen Familie von Hofleuten geboren und diente in seiner Jugend als Verwalter der Güter des Fürsten Iwan Penkow; und dort schmiedete der Neid der Menschen seine Heiligkeit, denn man verleumdete ihn als Ehebrecher mit der Frau des Fürsten, und der Fürst, der die Lüge glaubte, warf ihn in eine unterirdische Zelle, wo der Unschuldige zwei Jahre lang im Dunkeln auf Stroh sass und man ihm Hafer und Wasser hinabwarf.", "patron": "Angerufen um die Gefangenen; um die Lehrer der Kinder."},

"First Translation of the relics of Saint Herman, Archbishop of Kazan":
{"type": "Erzbischof · 16. Jh.", "life": "Der heilige Hierarch German, Erzbischof von Kasan, wurde zu Stariza aus dem adligen Geschlechte der Sadyrew-Polew geboren, und da er im Kloster von Wolokolamsk die Mönchsweihe empfing, wurde er in der Schule des ehrwürdigen Iosif geformt und für seine Gelehrsamkeit, sein asketisches Leben und seine Arbeit am Abschreiben von Büchern bekannt. Als die neu eroberten Länder von Kasan dem Evangelium geöffnet wurden, wurde er mit dem ehrwürdigen Gurij zu ihrer Erleuchtung gesandt und gründete zu Swijaschsk das Kloster der Entschlafung der Gottesmutter, das zum Mittelpunkte der Mission unter den Völkern an der Wolga wurde.", "patron": "Angerufen um die Missionare; um die Erleuchtung der Länder von Kasan."},

"Venerable Longinus the Gatekeeper of the Kyiv Caves":
{"type": "Mönch · 14. Jh.", "life": "Der ehrwürdige Longin der Pförtner von den Höhlen von Kyjiw erfüllte seinen mönchischen Gehorsam an den Toren der grossen Lawra, und sein inständiges Gebet und seine demütige Arbeitsliebe wurden vom Herrn mit der Gabe der Unterscheidung belohnt, so dass der Pförtner des Klosters ein Pförtner der Seelen wurde.", "patron": "Angerufen um die Pförtner; um die Türhüter."},

"Hieromartyrs John the Bishop and Jacob (James) the Presbyter, of Persia":
{"type": "Märtyrer · 4. Jh.", "life": "Die Priestermärtyrer Johannes der Bischof und Jakob der Presbyter, der Eiferer genannt, litten in Persien unter der Regierung des Königs Schapur des Zweiten, des grossen Verfolgers der Kirche jenseits der östlichen Grenze des Reiches. Da sie den wahren Glauben mit Freimut predigten, zogen sie viele fromme Seelen zu Christus, und das Wachstum der Kirche durch ihre Arbeit brachte sie vor den König.", "patron": "Angerufen um die Kirche unter der persischen Verfolgung."},

"Leavetaking of the Nativity of the Mother of God":
{"type": "Fest", "life": "Dies ist die Verabschiedung des Festes der Geburt der Allheiligen Gottesgebärerin, der letzte Tag jener Festzeit, in welcher die Kirche die Geburt der Gottesmutter feiert. An diesem Tage werden die Hymnen und die Lesungen des Festes noch einmal in ihrer Fülle gesungen, und die Gläubigen nehmen von dem Feste Abschied, nachdem sie mit seiner Freude erfüllt worden sind.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Uncovering of the relics of Saint Vsévolod (Gabriel) of Pskov":
{"type": "Fürst · 12. Jh.", "life": "An diesem Tag begeht die Kirche die Auffindung der Reliquien des heiligen Fürsten Wsewolod von Pskow, in der heiligen Taufe Gabriel genannt, die im Jahr 1192 geschah. Als Enkel Wladimir Monomachs und Sohn des heiligen Mstislaw des Grossen herrschte Wsewolod von Jugend auf über Nowgorod mit Gerechtigkeit und offenen Händen, baute Kirchen, speiste in der Hungersnot die Armen auf eigene Kosten und führte die Heere der Stadt.", "patron": "Angerufen um die Herrscher; um die Erbauer."},
}
